339 test/ci_pub_get_retry_guard_test.dart
// gh-1310 — every flutter_app `flutter pub get --enforce-lockfile` in CI
// rides ONE shared composite action with the #726 bounded retry.
//
// The v1.0.513 tag CI went red on 13 legs from a deterministic cause
// (gh-1299: release commit without the lockfile refresh). #1304 fixed that
// and hardened the release path — but the very next main run went red AGAIN
// on a different leg (ci.yml build-macos): pub has NO retry for its
// git-dependency mirror clones (flutter_js, flutter_js_widget_runtime), so
// one transient "Connection reset by peer" on github.com:443 kills the leg
// — and every lockfile-refresh commit cold-misses the flutter-action pub
// cache, forcing fresh clones exactly when releases land. build-mobile.yml
// solved this class for its iOS leg back in #726 (bounded retry + backoff +
// deterministic-skew fail-fast), but the pattern stayed trapped in ONE step
// while 21 other workflow steps ran the same network roulette bare.
//
// Deliberately YAML-level asserts (the nightly_desktop_leg_guard_test.dart
// / store_automation_guard_test.dart static pattern):
//  AC1  the shared action exists, is composite, and carries the #726
//       retry loop with the gh-1265/PR-1268 deterministic-skew fail-fast,
//  AC2  NO workflow run-step resolves flutter_app itself anymore — every
//       flutter_app pub get goes through `./.github/actions/flutter-pub-get`
//       (a future bare `cd flutter_app && flutter pub get` is a test red,
//       not a silent network roulette), and
//  AC3  each workflow still resolves flutter_app exactly as many times as
//       it did before the migration (a refactor that DELETES a pub-get
//       step must red here, not silently skip resolution),
//  AC4  a job's first flutter_app resolution is the enforced one — the
//       shared action runs BEFORE any step that consumes flutter_app with
//       a bare `flutter` command (office-addin.yml: flutter test's
//       implicit pub get would otherwise be the first, unenforced and
//       unretried, resolution), and the AC2 detector itself is unit-tested
//       against both `flutter_app` and `./flutter_app` working-directory
//       spellings (gh-1310 rework review threads 1-3).
import 'dart:io';

import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

String read(String path) => File(path).readAsStringSync();

const actionUses = './.github/actions/flutter-pub-get';
const actionPath = '.github/actions/flutter-pub-get/action.yml';

/// The seven workflows that resolved flutter_app with
/// `flutter pub get --enforce-lockfile` before the gh-1310 migration.
const workflows = [
  '.github/workflows/ci.yml',
  '.github/workflows/nightly.yml',
  '.github/workflows/build-mobile.yml',
  '.github/workflows/build-macos.yml',
  '.github/workflows/browser-ext.yml',
  '.github/workflows/office-addin.yml',
  '.github/workflows/pages.yml',
];

/// Expected number of `uses: ./.github/actions/flutter-pub-get` steps per
/// workflow — the exact step count that ran `flutter pub get
/// --enforce-lockfile` before the migration. A refactor that drops a
/// resolution step fails AC3 instead of silently skipping pub get.
const expectedUsesPerWorkflow = {
  // 10 pre-migration resolutions + 1 (gh-1310 rework, review thread 1): the
  // release-tag job warms the pub cache through the action BEFORE
  // tag_release.sh's own enforce-lockfile smoke.
  // 11 + 1 (issue #1267 N1, review round 3): the new flutter-app-exzone leg
  // resolves flutter_app through the shared action (bounded retry + skew
  // fail-fast) before its macOS `flutter test test/apps` run — a bare pub
  // get there would be exactly the network roulette AC2 exists to stop.
  // 12 + 1 (issue #1267 N2): the flutter-app-lock-smoke legs resolve
  // flutter_app through the shared action before their linux/windows
  // release builds — the smoke that catches a floated transitive (#1265)
  // must itself resolve against the COMMITTED lockfile, never re-float it.
  // 12 - 1 (gh-1522): the release-tag job is retired with the bot bump flow
  // — releases cut tags without touching files, so nothing on the release
  // path resolves flutter_app anymore. gh-1537 needs no release-tag.yml
  // entry either: with the post-merge main CI run retired there are no
  // main-push events, and the tag-only release (gh-1522) cuts its tag
  // inside the ci.yml release job on schedule/dispatch arms.
  '.github/workflows/ci.yml': 12,
  // gh-1538: nightly slimmed to builds + integration-only — the
  // full-quality / cli-visual / flutter-app-macos jobs (3 of the 4
  // pre-migration resolutions) are gone as pre-merge-gate duplication.
  // Only build-release resolves flutter_app now.
  '.github/workflows/nightly.yml': 1,
  '.github/workflows/build-mobile.yml': 4,
  '.github/workflows/build-macos.yml': 1,
  '.github/workflows/browser-ext.yml': 1,
  '.github/workflows/office-addin.yml': 1,
  '.github/workflows/pages.yml': 1,
};

/// Every `steps:` entry of every job in [workflowPath] as YamlMap steps
/// (jobs with `uses:` reusable-workflow calls have no steps and yield
/// nothing).
Iterable<YamlMap> stepsOf(String workflowPath) sync* {
  final root = loadYaml(read(workflowPath)) as YamlMap;
  final jobs = root['jobs'] as YamlMap;
  for (final job in jobs.values) {
    final steps = (job as YamlMap)['steps'];
    if (steps is! YamlList) continue;
    for (final step in steps) {
      if (step is YamlMap) yield step;
    }
  }
}

/// Every run-step in [workflowPath] as (run, workingDirectory).
Iterable<({String run, String? workingDirectory})> runStepsOf(
  String workflowPath,
) sync* {
  for (final step in stepsOf(workflowPath)) {
    if (step['run'] is! String) continue;
    yield (
      run: step['run'] as String,
      workingDirectory: step['working-directory'] as String?,
    );
  }
}

/// The AC2 regression class: run-steps that resolve flutter_app with a
/// bare `flutter pub get` instead of the shared action. A step counts
/// when the command mentions flutter_app OR runs inside flutter_app.
List<({String run, String? workingDirectory})> bareFlutterAppPubGetRunSteps(
  Iterable<({String run, String? workingDirectory})> steps,
) {
  return steps
      // Normalize the `./` spelling so `working-directory: ./flutter_app`
      // counts the same as `working-directory: flutter_app` (review
      // thread 3 — the heuristic must not depend on spelling).
      .map(
        (step) => (
          run: step.run,
          workingDirectory: step.workingDirectory?.replaceFirst(
            RegExp(r'^\./'),
            '',
          ),
        ),
      )
      .where(
        (step) =>
            step.run.contains('flutter pub get') &&
            (step.run.contains('flutter_app') ||
                (step.workingDirectory ?? '').startsWith('flutter_app')),
      )
      .toList();
}

void main() {
  group('gh-1310 — flutter_app pub get rides the shared retry action', () {
    test('AC1: the composite action exists and is a composite action', () {
      final action = loadYaml(read(actionPath)) as YamlMap;
      final runs = action['runs'] as YamlMap;
      expect(runs['using'], 'composite');
      expect(runs['steps'], isA<YamlList>());
    });

    test('AC1: the action carries the #726 bounded retry', () {
      final body = read(actionPath);
      expect(body, contains('for attempt in 1 2 3'));
      expect(
        body,
        contains('sleep 15'),
        reason:
            'the retry must back off — a tight loop hammers a '
            'runner whose network is already flapping (#726)',
      );
      // pub runs its git-dep clones non-interactively; a credential
      // prompt would hang the leg until the job timeout.
      expect(body, contains('GIT_TERMINAL_PROMPT'));
      expect(
        body,
        contains('--enforce-lockfile'),
        reason:
            'the shared action is the ONE sanctioned flutter_app '
            'resolution shape — it must keep enforcing the committed '
            'lockfile (gh-1265 AC2)',
      );
    });

    test('AC1: the action fails fast on a deterministic lockfile skew', () {
      // PR #1268 review thread 3: a pubspec/…

  }
}

// ============================================================================
// Per-bundle processing — register CodeAssets from resolved libDir
// ============================================================================

/// Cross-package coordination for a shared native bundle. Inspects the marker:
///   - (present: true)  → exact (bundle, version) already cached → dedup
///   - (present: false) → caller fetches (absent, legacy, OR same-owner upgrade)
///   - THROWS           → a DIFFERENT owner placed a DIFFERENT version (skew).
/// Call FIRST in _processBundle. The existing _resolveLibDir/_hasMainLib do the
/// actual from-cache dedup; the guard's load-bearing job is the throw on skew.
({bool present}) _guardAndCheckPresent(_NativeBundle bundle) {
  final existing = _readMarker(bundle);
  // absent / legacy → fetch.
  if (existing == null) return (present: false);
  // exact match → dedup.
  if (existing.version == bundle.version) return (present: true);
  // same-owner upgrade → fetch.
  if (existing.owner == _packageName) return (present: false);
  throw StateError(
    'Native library conflict for "${bundle.namespace}": '
    'this package ($_packageName) needs version ${bundle.version}, '
    'but "${existing.owner}" already placed version ${existing.version} '
    'in the shared cache (${bundle.cacheRoot().path}). '
    'Align the ${bundle.namespace} bundle version across these packages '
    "(each package's hook/build.dart pins it).",
  );
}

Future<void> _processBundle({
  required _NativeBundle bundle,
  required BuildInput input,
  required BuildOutputBuilder output,
  required OS os,
  required String dirName,
}) async {
  // Skip the bundle entirely if it has no checksum for this platform.
  // Both bundles use this as the "is this target supported" gate.
  if (!bundle.checksums.containsKey(bundle.archiveName(dirName))) return;

  // Cross-package version-skew guard (throws on a different owner declaring a
  // different version of this shared bundle). Match/absent/same-owner are no-ops
  // here — _resolveLibDir below does the actual dedup; this call exists so the
  // THROW happens before any fetch/wipe on a skew.
  _guardAndCheckPresent(bundle);

  // Sole owner of libLiteRtLm now; the single-registrant marker is vestigial
  // (cache-dedup only).
  //
  // Single-registrant: only the bundle's owner (the first hook to write the
  // marker) registers the shared CodeAssets. A non-owner package sharing the
  // same bundle (e.g. embeddings sharing litertlm's libLiteRtLm) ensures the
  // cache is populated (dedup/download below) but must NOT re-register the same
  // dylib — Native Assets errors on a duplicate bundled filename, and both FFI
  // loaders open it by a FIXED basename (libLiteRtLm.so / LiteRtLm.framework),
  // so exactly one package must bundle it. At runtime the non-owner's
  // DynamicLibrary.open(filename) resolves the owner-bundled dylib.
  //
  // KNOWN LIMITATION (orphaned-owner edge case): the owner is persisted in the
  // shared-cache marker ACROSS builds. A Dart build hook is sandboxed — it sees
  // only its own packageRoot; BuildInput.assets/metadata expose ONLY direct
  // dependencies (hooks config.dart, ToBuildHooks dartdoc), and litertlm /
  // embeddings deliberately don't depend on each other (embeddings is
  // autonomous). So a hook CANNOT learn the current build's package set and
  // CANNOT recompute the registrant per-build. If the recorded owner is later
  // dropped from the app's deps and the survivor rebuilds without `flutter
  // clean`, the survivor reads the stale owner, skips registration, and nobody
  // bundles the dylib → an opaque dlopen "no such file" at first use. Fix:
  // `flutter clean` + delete the flutter_gemma native cache (see each package's
  // README troubleshooting). Upstream deliberately chose "one registrant + error
  // on conflict, no auto-dedup" (dart-lang/native#190, flutter#158214).
  //
  // Capture the owner state BEFORE _writeMarker below can overwrite it: a
  // non-owner dedup must not clobber the marker's owner to itself.
  final existingOwner = _readMarker(bundle)?.owner;
  final iAmRegistrant = existingOwner == null || existingOwner == _packageName;

  _invalidateBundleCacheIfStale(bundle);

  var libDir = _resolveLibDir(bundle, dirName, input.packageRoot, os);
  libDir ??= await _downloadAndExtract(bundle, dirName);
  // Null now means one thing only: no checksum registered for this platform,
  // i.e. we ship nothing for it on purpose. Every real failure throws.
  if (libDir == null) return;

  final prebuiltDir = libDir.uri;
  final mainFileName = _dylibFileName(os, bundle.mainLibName);
  final mainFileUri = prebuiltDir.resolve(mainFileName);
  if (!File.fromUri(mainFileUri).existsSync()) {
    // We got a directory — from the cache, a local prebuilt, or a verified
    // download — and the one library the bundle exists to deliver is not in
    // it. Returning here registered no CodeAsset and reported success, so a
    // half-populated cache shipped as a working build.
    throw StateError(
      'flutter_gemma: ${bundle.namespace} $dirName resolved to '
      '${prebuiltDir.toFilePath()} but $mainFileName is missing from it.\n'
      'The directory is present but incomplete — most often a cache left over '
      'from an interrupted extract. Delete it, then `flutter clean` and build '
      'again. NOT `flutter pub get`: pub get does not run build hooks, so it '
      'will not repopulate the cache (measured — output.json mtimes unchanged).',
    );
  }

  // Commit point: marker written only after the dylib is confirmed in place.
  // Gated on iAmRegistrant so a non-owner dedup never clobbers the owner.
